      "task": "detect_spatial_columns",
      "player": "spatial_temporal_specialist",
      "rationale": "Detect spatial columns in the single CSV resource to identify coordinate/geometry fields for spatial coverage analysis.",
      "inputs": {},
      "outputs": [
        "spatial_detection"
      ]
    },
    {
      "task": "get_temporal_extent",
      "player": "spatial_temporal_specialist",
      "rationale": "Calculate the temporal extent (start/end dates) from detected temporal columns to populate temporalCoverage.",
      "inputs": {
        "detection": "temporal_detection"
      },
      "outputs": [
        "temporal_extent"
      ]
    },
    {
      "task": "get_spatial_extent",
      "player": "spatial_temporal_specialist",
      "rationale": "Calculate the spatial bounding box from detected spatial columns (separate lat/lon) to populate spatialCoverage. If tuple coordinates are detected, this step will use get_spatial_extent_from_tuple_column instead.",
      "inputs": {
        "detection": "spatial_detection"
      },
      "outputs": [
        "spatial_extent"
      ]
    },
    {
      "task": "generate_metadata",
      "player": "croissant_inaturalist_metadata_generator",
      "rationale": "Generate the final iNaturalist Croissant metadata with spatialCoverage and temporalCoverage using the analyzed extent artifacts and the metadata standard.",
      "inputs": {
        "metadata_standard": "metadata_standard",
        "spatial_temporal": "spatial_extent"
      },
      "outputs": [
        "metadata_output"
      ]
    }
  ]
}
```

